import heapq
import random


class Node:
    __slots__ = ('val', 'l', 'r')

    def __init__(self, val):
        self.val = val
        self.l = None
        self.r = None


def merge(a, b):
    """随机化合并两个堆，返回新根。期望 O(log n)"""
    if a is None:
        return b
    if b is None:
        return a
    if b.val < a.val:
        a, b = b, a
    if random.getrandbits(1):
        a.l, a.r = a.r, a.l
    a.l = merge(a.l, b)
    return a


def insert(root, val):
    return merge(root, Node(val))


def pop_min(root):
    if root is None:
        return None, None
    return merge(root.l, root.r), root.val


if __name__ == '__main__':
    random.seed(3)
    h = None
    ref = []
    for _ in range(8000):
        op = random.random()
        if op < 0.55 or not ref:
            v = random.randint(0, 100000)
            h = insert(h, v)
            heapq.heappush(ref, v)
        else:
            h, m = pop_min(h)
            r = heapq.heappop(ref)
            assert m == r, (m, r)
        if h is None:
            assert not ref
    # 双堆合并
    h1 = h2 = None
    r1, r2 = [], []
    for v in [4, 2, 8, 1]:
        h1 = insert(h1, v); r1.append(v)
    for v in [9, 3, 0, 5]:
        h2 = insert(h2, v); r2.append(v)
    h = merge(h1, h2)
    out = []
    while h is not None:
        h, m = pop_min(h)
        out.append(m)
    assert out == sorted(r1 + r2), (out, r1, r2)
    print('randomized heap: All tests passed.')
